arguments.command:
env OPENBLAS_NUM_THREADS=1 OMP_NUM_THREADS=1 python -B -c "import numpy as np; import pandas as pd; from catboost import CatBoostRegressor; from analyze_supercon import COMPS, CU, ELEMENTS, FEATURES, N, POOL, RE, Y; rows=[]
for c in COMPS:
 a=c.get('Ba',0)+c.get('Sr',0); ref=a/2 if a>0 else max(c.get('Cu',0),1); f={e:c.get(e,0)/ref for e in ELEMENTS if e!='O'}; f.update(RE=sum(c.get(e,0) for e in RE)/ref, RE_non_PrCe=sum(c.get(e,0) for e in RE if e not in ['Pr','Ce'])/ref, TlHg=(c.get('Tl',0)+c.get('Hg',0))/ref, BiPb=(c.get('Bi',0)+c.get('Pb',0))/ref, CaMg=(c.get('Ca',0)+c.get('Mg',0))/ref, BaSr=a/ref, specified_O=c.get('O',0)/ref if c.get('O',0)!=1 else -1, Cu_dopants=sum(c.get(e,0) for e in ['Fe','Co','Ni','Zn','Mn','Ga','Al'])/ref, oxide_cuprate=int(c.get('O',0)>0 and c.get('Cu',0)>0)); rows.append(f)
S=pd.DataFrame(rows); combined=pd.concat([S,FEATURES],axis=1); predictions={}; idx=np.flatnonzero(CU[:N])
for name, frame in [('original',FEATURES),('combined',combined)]:
 for seed in [21,42,123,2026,512]:
  model=CatBoostRegressor(iterations=1100,depth=4,learning_rate=.035,l2_leaf_reg=4,verbose=False,thread_count=4,random_seed=seed,allow_writing_files=False); model.fit(frame.iloc[idx],Y[idx]); predictions[f'{name}_{seed}']=model.predict(frame.iloc[N:])
table=pd.DataFrame(predictions,index=POOL.candidate_id); table['mean']=table.mean(axis=1); print(table.loc[['c046','c097','c029','c034','c084','c081','c044','c075']].sort_values('mean',ascending=False).round(2).to_string())"

